  auto DATA__ = DATA ? _fbb.CreateVectorOfSortedTables<APPDataRef>(DATA) : 0;
  auto SOURCES__ = SOURCES ? _fbb.CreateVectorOfSortedTables<APPSourceRef>(SOURCES) : 0;
